1	/**
2	 * TeamConnectionService — gerencia o roster "minha equipe" (Slice 1, R1/R2).
3	 *
4	 * Modelo: aresta bilateral consentida (handshake UMA vez).
5	 * - Empresa adiciona o freela via QR / link / telefone → conexão nasce 'pending'.
6	 * - Freela aceita → 'accepted'. Convites de turno seguintes NÃO re-pedem handshake.
7	 * - Freela pode sair/bloquear → 'blocked'.
8	 *
9	 * Avisos do architect (ADR-001):
10	 * - Criar-turno e aceite NÃO chamam reserve_escrow (postpago é Slice 2).
11	 * - A empresa NÃO pode forjar 'accepted' (RLS WITH CHECK).
12	 * - Envio de SMS para o canal 'phone' é Slice 4 — aqui só criamos o registro.
13	 */
14	
15	import { supabase } from '../lib/supabase';
16	import { logError } from '../lib/logger';
17	import type {
18	  TeamConnection,
19	  TeamConnectionSource,
20	  TeamConnectionStatus,
21	  TeamMember,
22	  MyStore,
23	  WorkerProfile,
24	  CompanyProfile,
25	} from '../types';
26	
27	// ---------------------------------------------------------------------------
28	// Tipos auxiliares internos
29	// ---------------------------------------------------------------------------
30	
31	export interface CreateConnectionResult {
32	  connection: TeamConnection | null;
33	  error?: string;
34	  /** true quando a conexão já existia (idempotência de convite de equipe) */
35	  alreadyExists?: boolean;
36	}
37	
38	export interface UpdateConnectionResult {
39	  success: boolean;
40	  error?: string;
41	}
42	
43	/**
44	 * Token de convite de conexão via link (R1-b).
45	 * Gerado pelo service e armazenado como metadata na conexão.
46	 * Resolução: o link traz o token → service lê a conexão pending → worker aceita.
47	 */
48	export interface ConnectionInviteToken {
49	  token: string;
50	  /** URL pública do link de convite */
51	  url: string;
52	}
53	
54	// ---------------------------------------------------------------------------
55	// Helpers de query de empresa (session)
56	// ---------------------------------------------------------------------------
57	
58	/**
59	 * Retorna o `company_id` da empresa autenticada.
60	 * Lança erro se não houver sessão ou se o usuário não for empresa.
61	 */
62	async function getAuthenticatedCompanyId(): Promise<string> {
63	  const {
64	    data: { user },
65	  } = await supabase.auth.getUser();
66	  if (!user) throw new Error('Sessão expirada. Faça login novamente.');
67	
68	  const { data: company, error } = await supabase
69	    .from('companies')
70	    .select('id')
71	    .eq('owner_id', user.id)
72	    .maybeSingle();
73	
74	  if (error) throw error;
75	  if (!company) throw new Error('Perfil de empresa não encontrado.');
76	
77	  return company.id as string;
78	}
79	
80	// ---------------------------------------------------------------------------
81	// TeamConnectionService
82	// ---------------------------------------------------------------------------
83	
84	export const TeamConnectionService = {
85	  // -------------------------------------------------------------------------
86	  // EMPRESA: adicionar freela à equipe
87	  // -------------------------------------------------------------------------
88	
89	  /**
90	   * Adiciona um worker ao roster da empresa (cria conexão 'pending').
91	   *
92	   * @param workerId  UUID do worker (a câmera/scan é responsabilidade da UI).
93	   * @param source    Canal de origem: 'qr' | 'link' | 'phone'.
94	   *
95	   * Canal 'phone': cria o registro pending; o envio de SMS é Slice 4 (NÃO chamado aqui).
96	   * Canal 'link':  gera um token estável; use `generateInviteToken()` para obter a URL.
97	   * Canal 'qr':    a UI fornece o workerId após decode do QR; apenas cria a conexão.
98	   *
99	   * Idempotente: se a conexão já existir retorna `alreadyExists: true` sem erro.
100	   */
101	  async addToTeam(
102	    workerId: string,
103	    source: TeamConnectionSource,
104	  ): Promise<CreateConnectionResult> {
105	    try {
106	      const companyId = await getAuthenticatedCompanyId();
107	
108	      // Verificar se já existe (idempotência — UNIQUE team_connections_unique_pair)
109	      const { data: existing, error: checkErr } = await supabase
110	        .from('team_connections')
111	        .select('*')
112	        .eq('company_id', companyId)
113	        .eq('worker_id', workerId)
114	        .maybeSingle();
115	
116	      if (checkErr) {
117	        logError('teamConnection.addToTeam.check', checkErr);
118	        return { connection: null, error: 'Erro ao verificar conexão existente.' };
119	      }
120	
121	      if (existing) {
122	        return {
123	          connection: existing as TeamConnection,
124	          alreadyExists: true,
125	        };
126	      }
127	
128	      const { data, error } = await supabase
129	        .from('team_connections')
130	        .insert({
131	          company_id: companyId,
132	          worker_id: workerId,
133	          status: 'pending' as TeamConnectionStatus,
134	          source,
135	        })
136	        .select()
137	        .single();
138	
139	      if (error) {
140	        // Corrida: insert concorrente pode ter criado antes de nós (race condition)
141	        if (error.code === '23505') {
142	          return { connection: null, alreadyExists: true };
143	        }
144	        logError('teamConnection.addToTeam.insert', error);
145	        return { connection: null, error: 'Não foi possível adicionar o freela à equipe.' };
146	      }
147	
148	      return { connection: data as TeamConnection };
149	    } catch (err) {
150	      logError('teamConnection.addToTeam', err);
151	      return {
152	        connection: null,
153	        error: err instanceof Error ? err.message : 'Erro inesperado.',
154	      };
155	    }
156	  },
157	
158	  /**
159	   * Gera (ou reutiliza) um token de convite de link para a empresa atual.
160	   *
161	   * Estratégia: o token é o `company_id` codificado em base64url + timestamp truncado,
162	   * suficiente para o MVP (não requer tabela separada de tokens).
163	   * A UI monta a URL: `https://app.worki.com/convite/{token}`.
164	   * O resolver do link chama `resolveInviteToken(token)` para descobrir a empresa.
165	   */
166	  generateInviteToken(companyId: string): ConnectionInviteToken {
167	    // Token simples, não criptográfico — o RLS protege o DB; o token só identifica a empresa.
168	    const payload = `${companyId}:${Date.now()}`;
169	    const token = btoa(payload).replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, '');
170	    const url = `${window.location.origin}/convite/${token}`;
171	    return { token, url };
172	  },
173	
174	  /**
175	   * Resolve um token de link de convite → retorna o `company_id`.
176	   * Retorna null se o token for inválido ou malformado.
177	   */
178	  resolveInviteToken(token: string): string | null {
179	    try {
180	      const padded = token.replace(/-/g, '+').replace(/_/g, '/');
181	      const payload = atob(padded);
182	      const [companyId] = payload.split(':');
183	      if (!companyId || companyId.length < 30) return null;
184	      return companyId;
185	    } catch {
186	      return null;
187	    }
188	  },
189	
190	  /**
191	   * Adiciona um worker via token de link de convite.
192	   * A empresa é extraída do token; o worker aceita a conexão no próximo passo.
193	   */
194	  async addToTeamByToken(
195	    token: string,
196	    workerId: string,
197	  ): Promise<CreateConnectionResult> {
198	    const companyId = this.resolveInviteToken(token);
199	    if (!companyId) {
200	      return { connection: null, error: 'Link de convite inválido ou expirado.' };
201	    }
202	
203	    // Inserir a conexão diretamente (o worker dispara isso via link)
204	    // O RLS de INSERT exige que company_id IN companies WHERE owner_id = auth.uid().
205	    // Aqui o worker não é dono da company → não pode usar a policy de empresa.
206	    // Solução: o link de convite é resolvido pela EMPRESA (ela abre o link no seu contexto)
207	    // OU a inserção usa invokeFunction para uma Edge Function se precisarmos do worker-side.
208	    // Para o MVP, o fluxo de link abre na sessão da empresa → addToTeam normal.
209	    // Se o fluxo for "worker clica no link" → vira uma pending da empresa pendente de iniciativa.
210	    // No MVP v1, o link é enviado pela empresa para o worker fora do app; o worker aceita depois.
211	    // Registro da conexão: a empresa cria pending via addToTeam; o worker aceita via acceptConnection.
212	    // Esta função é um helper de conveniência para testes e fluxos alternativos.
213	    const { data: company, error: cErr } = await supabase
214	      .from('companies')
215	      .select('id, owner_id')
216	      .eq('id', companyId)
217	      .single();
218	
219	    if (cErr || !company) {
220	      return { connection: null, error: 'Empresa do convite não encontrada.' };
221	    }
222	
223	    // Verificar existência
224	    const { data: existing } = await supabase
225	      .from('team_connections')
226	      .select('*')
227	      .eq('company_id', companyId)
228	      .eq('worker_id', workerId)
229	      .maybeSingle();
230	
231	    if (existing) {
232	      return { connection: existing as TeamConnection, alreadyExists: true };
233	    }
234	
235	    const { data, error } = await supabase
236	      .from('team_connections')
237	      .insert({
238	        company_id: companyId,
239	        worker_id: workerId,
240	        status: 'pending' as TeamConnectionStatus,
241	        source: 'link' as TeamConnectionSource,
242	      })
243	      .select()
244	      .single();
245	
246	    if (error) {
247	      if (error.code === '23505') {
248	        return { connection: null, alreadyExists: true };
249	      }
250	      logError('teamConnection.addToTeamByToken.insert', error);
251	      return { connection: null, error: 'Não foi possível registrar o convite.' };
252	    }
253	
254	    return { connection: data as TeamConnection };
255	  },
256	
257	  // -------------------------------------------------------------------------
258	  // WORKER: aceitar ou bloquear/sair
259	  // -------------------------------------------------------------------------
260	
261	  /**
262	   * Worker aceita uma conexão pendente (pending → accepted).
263	   * Máquina de estados validada aqui: só aceita se status for 'pending'.
264	   */
265	  async acceptConnection(connectionId: string): Promise<UpdateConnectionResult> {
266	    try {
267	      const {
268	        data: { user },
269	      } = await supabase.auth.getUser();
270	      if (!user) return { success: false, error: 'Sessão expirada.' };
271	
272	      // Validar estado atual (máquina de estados no service — ADR-001)
273	      const { data: current, error: fetchErr } = await supabase
274	        .from('team_connections')
275	        .select('id, status, worker_id')
276	        .eq('id', connectionId)
277	        .maybeSingle();
278	
279	      if (fetchErr) {
280	        logError('teamConnection.acceptConnection.fetch', fetchErr);
281	        return { success: false, error: 'Conexão não encontrada.' };
282	      }
283	      if (!current) return { success: false, error: 'Conexão não encontrada.' };
284	      if (current.worker_id !== user.id) {
285	        return { success: false, error: 'Você não é o freela desta conexão.' };
286	      }
287	      if (current.status !== 'pending') {
288	        return {
289	          success: false,
290	          error: `Transição inválida: status atual é '${current.status}', esperado 'pending'.`,
291	        };
292	      }
293	
294	      const { error } = await supabase
295	        .from('team_connections')
296	        .update({
297	          status: 'accepted' as TeamConnectionStatus,
298	          accepted_at: new Date().toISOString(),
299	        })
300	        .eq('id', connectionId)
301	        .eq('worker_id', user.id);
302	
303	      if (error) {
304	        logError('teamConnection.acceptConnection.update', error);
305	        return { success: false, error: 'Erro ao aceitar conexão.' };
306	      }
307	
308	      return { success: true };
309	    } catch (err) {
310	      logError('teamConnection.acceptConnection', err);
311	      return {
312	        success: false,
313	        error: err instanceof Error ? err.message : 'Erro inesperado.',
314	      };
315	    }
316	  },
317	
318	  /**
319	   * Worker sai/bloqueia uma empresa (→ 'blocked').
320	   * Funciona para status 'pending' (recusar convite de equipe) ou 'accepted' (sair).
321	   */
322	  async blockConnection(connectionId: string): Promise<UpdateConnectionResult> {
323	    try {
324	      const {
325	        data: { user },
326	      } = await supabase.auth.getUser();
327	      if (!user) return { success: false, error: 'Sessão expirada.' };
328	
329	      // Validar propriedade (deve ser o worker da conexão)
330	      const { data: current, error: fetchErr } = await supabase
331	        .from('team_connections')
332	        .select('id, status, worker_id')
333	        .eq('id', connectionId)
334	        .maybeSingle();
335	
336	      if (fetchErr || !current) {
337	        logError('teamConnection.blockConnection.fetch', fetchErr);
338	        return { success: false, error: 'Conexão não encontrada.' };
339	      }
340	      if (current.worker_id !== user.id) {
341	        return { success: false, error: 'Você não é o freela desta conexão.' };
342	      }
343	      if (current.status === 'blocked') {
344	        return { success: true }; // já bloqueada — idempotente
345	      }
346	
347	      const { error } = await supabase
348	        .from('team_connections')
349	        .update({
350	          status: 'blocked' as TeamConnectionStatus,
351	          blocked_by: user.id,
352	        })
353	        .eq('id', connectionId)
354	        .eq('worker_id', user.id);
355	
356	      if (error) {
357	        logError('teamConnection.blockConnection.update', error);
358	        return { success: false, error: 'Erro ao bloquear conexão.' };
359	      }
360	
361	      return { success: true };
362	    } catch (err) {
363	      logError('teamConnection.blockConnection', err);
364	      return {
365	        success: false,
366	        error: err instanceof Error ? err.message : 'Erro inesperado.',
367	      };
368	    }
369	  },
370	
371	  // -------------------------------------------------------------------------
372	  // EMPRESA: listar equipe aceita ("minha equipe")
373	  // -------------------------------------------------------------------------
374	
375	  /**
376	   * Lista os membros aceitos da equipe da empresa autenticada.
377	   * Retorna conexões 'accepted' com perfil do worker embutido.
378	   */
379	  async listTeamMembers(): Promise<TeamMember[]> {
380	    try {
381	      const companyId = await getAuthenticatedCompanyId();
382	
383	      const { data, error } = await supabase
384	        .from('team_connections')
385	        .select(
386	          `
387	          *,
388	          worker:workers (
389	            id,
390	            full_name,
391	            avatar_url,
392	            photo_url,
393	            primary_role,
394	            roles,
395	            rating_average,
396	            reviews_count,
397	            completed_jobs_count,
398	            phone,
399	            city
400	          )
401	        `,
402	        )
403	        .eq('company_id', companyId)
404	        .eq('status', 'accepted')
405	        .order('accepted_at', { ascending: false });
406	
407	      if (error) {
408	        logError('teamConnection.listTeamMembers', error);
409	        return [];
410	      }
411	
412	      return ((data ?? []) as Array<TeamConnection & { worker: WorkerProfile }>).map(
413	        (row) => ({
414	          connection: {
415	            id: row.id,
416	            company_id: row.company_id,
417	            worker_id: row.worker_id,
418	            status: row.status,
419	            source: row.source,
420	            blocked_by: row.blocked_by,
421	            created_at: row.created_at,
422	            accepted_at: row.accepted_at,
423	            updated_at: row.updated_at,
424	          },
425	          worker: row.worker,
426	        }),
427	      );
428	    } catch (err) {
429	      logError('teamConnection.listTeamMembers', err);
430	      return [];
431	    }
432	  },
433	
434	  /**
435	   * Lista todas as conexões da empresa (pending + accepted + blocked).
436	   * Útil para a UI de gestão da equipe.
437	   */
438	  async listAllConnections(): Promise<TeamConnection[]> {
439	    try {
