535	
536	  /**
537	   * Lista conexões pendentes (convites de equipe) do worker autenticado.
538	   * Para a UI do worker aceitar/recusar convites de equipe.
539	   */
540	  async listPendingConnections(): Promise<TeamConnection[]> {
541	    try {
542	      const {
543	        data: { user },
544	      } = await supabase.auth.getUser();
545	      if (!user) return [];
546	
547	      const { data, error } = await supabase
548	        .from('team_connections')
549	        .select(
550	          `
551	          *,
552	          company:companies (
553	            id,
554	            name,
555	            logo_url,
556	            rating_average,
557	            industry,
558	            address
559	          )
560	        `,
561	        )
562	        .eq('worker_id', user.id)
563	        .eq('status', 'pending')
564	        .order('created_at', { ascending: false });
565	
566	      if (error) {
