1	-- Fix: Company owner cannot read their own company row after FORCE ROW LEVEL SECURITY
2	-- The previous migration applied FORCE RLS but no SELECT policy existed for the owner.
3	-- Also: jobs need public SELECT for browsing, and applications need proper policies.
4	
5	-- =============================================
6	-- COMPANIES: Owner can read/update their own company
7	-- =============================================
8	DO $$ BEGIN
9	  -- Drop overly restrictive policies if they exist
10	  DROP POLICY IF EXISTS "Companies are viewable by owner" ON companies;
11	  DROP POLICY IF EXISTS "Company owner can view own company" ON companies;
12	  DROP POLICY IF EXISTS "Company owner can update own company" ON companies;
13	  DROP POLICY IF EXISTS "Authenticated can view companies" ON companies;
14	  DROP POLICY IF EXISTS "Authenticated can insert companies" ON companies;
15	END $$;
16	
17	-- Owner can SELECT their own company
18	CREATE POLICY "Company owner can view own company"
19	ON companies FOR SELECT TO authenticated
20	USING (owner_id = auth.uid());
21	
22	-- Any authenticated user can view companies (for public profiles, job listings)
23	CREATE POLICY "Authenticated users can view companies"
24	ON companies FOR SELECT TO authenticated
25	USING (true);
26	
27	-- Owner can INSERT their company (onboarding)
28	CREATE POLICY "Users can create their company"
29	ON companies FOR INSERT TO authenticated
30	WITH CHECK (owner_id = auth.uid());
31	
32	-- Owner can UPDATE their company
33	CREATE POLICY "Company owner can update own company"
34	ON companies FOR UPDATE TO authenticated
35	USING (owner_id = auth.uid())
36	WITH CHECK (owner_id = auth.uid());
37	
38	-- =============================================
39	-- JOBS: Any authenticated user can view (for browsing)
40	-- =============================================
41	DO $$ BEGIN
42	  DROP POLICY IF EXISTS "Anyone can view open jobs" ON jobs;
43	  DROP POLICY IF EXISTS "Authenticated can view jobs" ON jobs;
44	  DROP POLICY IF EXISTS "Company owner can manage jobs" ON jobs;
45	END $$;
46	
47	-- All authenticated can view jobs (workers need to browse)
48	CREATE POLICY "Authenticated can view jobs"
49	ON jobs FOR SELECT TO authenticated
50	USING (true);
51	
52	-- Company owner can INSERT/UPDATE/DELETE their jobs
53	CREATE POLICY "Company owner can manage jobs"
54	ON jobs FOR ALL TO authenticated
55	USING (company_id IN (SELECT id FROM companies WHERE owner_id = auth.uid()))
56	WITH CHECK (company_id IN (SELECT id FROM companies WHERE owner_id = auth.uid()));
57	
58	-- =============================================
59	-- APPLICATIONS: Worker sees own, company sees for their jobs
60	-- =============================================
61	DO $$ BEGIN
62	  DROP POLICY IF EXISTS "Workers can view own applications" ON applications;
63	  DROP POLICY IF EXISTS "Companies can view applications for their jobs" ON applications;
64	  DROP POLICY IF EXISTS "Workers can insert applications" ON applications;
65	  DROP POLICY IF EXISTS "Workers can update own applications" ON applications;
66	END $$;
67	
68	CREATE POLICY "Workers can view own applications"
69	ON applications FOR SELECT TO authenticated
70	USING (worker_id = auth.uid());
71	
72	CREATE POLICY "Companies can view applications for their jobs"
73	ON applications FOR SELECT TO authenticated
74	USING (job_id IN (SELECT id FROM jobs WHERE company_id IN (SELECT id FROM companies WHERE owner_id = auth.uid())));
75	
76	CREATE POLICY "Workers can insert applications"
77	ON applications FOR INSERT TO authenticated
78	WITH CHECK (worker_id = auth.uid());
79	
80	CREATE POLICY "Workers can update own applications"
81	ON applications FOR UPDATE TO authenticated
82	USING (worker_id = auth.uid());
