143	CREATE OR REPLACE FUNCTION release_escrow(
144	    p_job_id UUID,
145	    p_worker_wallet_id UUID
146	)
147	RETURNS TABLE(escrow_id UUID, escrow_amount DECIMAL)
148	LANGUAGE plpgsql
149	SECURITY DEFINER
150	SET search_path = public
151	AS $$
152	DECLARE
153	    v_escrow_id UUID;
154	    v_amount DECIMAL;
155	    v_company_wallet_id UUID;
156	    v_caller_wallet_id UUID;
157	BEGIN
158	    -- Lock the escrow row for atomic update
159	    SELECT et.id, et.amount, et.company_wallet_id
160	    INTO v_escrow_id, v_amount, v_company_wallet_id
161	    FROM escrow_transactions et
162	    WHERE et.job_id = p_job_id AND et.status = 'reserved'
163	    FOR UPDATE;
164	
165	    IF NOT FOUND THEN
166	        RAISE EXCEPTION 'No reserved escrow found for job: %', p_job_id;
167	    END IF;
168	
169	    -- SECURITY: Validate caller is the company that owns the escrow
170	    -- Skip for trigger/service_role calls (auth.uid() is null)
171	    IF auth.uid() IS NOT NULL THEN
172	        SELECT id INTO v_caller_wallet_id
173	        FROM wallets WHERE user_id = auth.uid();
174	
175	        IF v_caller_wallet_id IS NULL OR v_caller_wallet_id != v_company_wallet_id THEN
176	            RAISE EXCEPTION 'Nao autorizado: voce nao e dono do escrow do job %', p_job_id;
177	        END IF;
178	    END IF;
179	
180	    UPDATE escrow_transactions
181	    SET status = 'released', released_at = NOW(), worker_wallet_id = p_worker_wallet_id
182	    WHERE id = v_escrow_id;
183	
184	    UPDATE wallets
185	    SET balance = balance + v_amount, updated_at = NOW()
186	    WHERE id = p_worker_wallet_id;
187	
188	    INSERT INTO wallet_transactions(wallet_id, amount, type, description, reference_id)
189	    VALUES (p_worker_wallet_id, v_amount, 'escrow_release', 'Pagamento recebido pela vaga', p_job_id::TEXT);
190	
191	    RETURN QUERY SELECT v_escrow_id, v_amount;
192	END;
193	$$;
