363	CREATE OR REPLACE FUNCTION auto_release_escrow_on_completion()
364	RETURNS TRIGGER
365	LANGUAGE plpgsql
366	SECURITY DEFINER
367	SET search_path = public
368	AS $$
369	DECLARE
370	    v_worker_wallet_id UUID;
371	    v_has_reserved_escrow BOOLEAN;
372	BEGIN
373	    -- Only trigger when status becomes 'completed' and both parties confirmed
374	    IF NEW.status = 'completed'
375	       AND NEW.company_checkout_confirmed_at IS NOT NULL
376	       AND NEW.worker_checkout_at IS NOT NULL
377	       AND (OLD.status IS DISTINCT FROM 'completed'
378	            OR OLD.company_checkout_confirmed_at IS NULL)
379	    THEN
380	        -- Check if there's a reserved escrow (prevents double-release)
381	        SELECT EXISTS(
382	            SELECT 1 FROM escrow_transactions
383	            WHERE job_id = NEW.job_id AND status = 'reserved'
384	        ) INTO v_has_reserved_escrow;
385	
386	        IF NOT v_has_reserved_escrow THEN
387	            RETURN NEW;
388	        END IF;
389	
390	        SELECT id INTO v_worker_wallet_id
391	        FROM wallets
392	        WHERE user_id = NEW.worker_id;
393	
394	        IF v_worker_wallet_id IS NULL THEN
395	            RAISE WARNING 'Worker % has no wallet, cannot auto-release escrow for job %',
396	                NEW.worker_id, NEW.job_id;
397	            RETURN NEW;
398	        END IF;
399	
400	        PERFORM release_escrow(NEW.job_id, v_worker_wallet_id);
401	
402	        RAISE NOTICE 'Auto-released escrow for job % to worker wallet %',
403	            NEW.job_id, v_worker_wallet_id;
404	    END IF;
405	
406	    RETURN NEW;
407	END;
408	$$;
